public long compressTimeBucket(long timeBucket, int dayStep) {
    // Ensure valid input
    if (timeBucket < 0 || dayStep <= 0) {
        throw new IllegalArgumentException("Invalid input values: timeBucket must be non-negative and dayStep must be positive.");
    }

    // Calculate the number of days in the sequence using modular arithmetic
    long daysInSequence = timeBucket % dayStep == 0 ? timeBucket / dayStep : timeBucket / dayStep + 1;

    // Calculate the start of the sequence as the first day of the sequence, subtracting a day to account for the offset
    long startOfSequence = timeBucket - timeBucket % dayStep - dayStep;

    // Return the start of the sequence
    return startOfSequence;
}

